import {onDeck} from './interior-growth.mjs';
import {roomVolumes,roomHeightAt} from './room-shapes.mjs';
import {structureFaces} from './architecture.mjs';
import {colors} from './generator.mjs';
import {terrainTriangles,terrainAt} from './terrain.mjs';
import {drawAvatar} from './scale-view.mjs';
const cached=new WeakMap();
export function terrainMesh(layout){if(!cached.has(layout))cached.set(layout,layout.terrain.surfaceMesh||terrainTriangles(layout.terrain));return cached.get(layout);}
export function waterPolygon(vertices){const result=[];for(let i=0;i<vertices.length;i++){const a=vertices[i],b=vertices[(i+1)%vertices.length],ia=a[1]<0,ib=b[1]<0;if(ia)result.push([a[0],.15,a[2]]);if(ia!==ib){const f=-a[1]/(b[1]-a[1]);result.push([a[0]+(b[0]-a[0])*f,.15,a[2]+(b[2]-a[2])*f]);}}return result;}
export function terrainColor(v){const h=v.reduce((s,p)=>s+p[1],0)/v.length;if(h<0)return '#194b5c';const a=v[1].map((x,k)=>x-v[0][k]),b=v[2].map((x,k)=>x-v[0][k]),nx=a[1]*b[2]-a[2]*b[1],ny=a[2]*b[0]-a[0]*b[2],nz=a[0]*b[1]-a[1]*b[0],s=.65+.35*Math.abs((nx*.4+ny*.8+nz*.3)/(Math.hypot(nx,ny,nz)||1));const base=h>65?[130,143,125]:[65,114,86];return `rgb(${base.map(x=>Math.round(x*s)).join(',')})`;}
export function renderMap(ctx,w,h,layout,state){const {mode,deck,yaw,pitch,zoom,selected,start,path=[],stack=false,surface=false}=state,c=layout.config,plan=mode==='plan',terrainMode=mode==='terrain',sy=Math.sin(yaw),cy=Math.cos(yaw),sp=Math.sin(pitch),cp=Math.cos(pitch),floor=layout.rooms.find(r=>onDeck(r,deck))?.y||0;
 const focus=layout.rooms.find(r=>r.id===state.focusRoom),length=focus?Math.max(focus.w*1.5,45):c.length,width=focus?Math.max(focus.d*1.5,45):c.width,height=focus?Math.max(focus.h*1.7,35):c.decks*c.height+c.mountain+c.lakeDepth;
 const scale=Math.min((w-70)/(plan?length:length*Math.abs(cy)+width*Math.abs(sy)),(h-150)/(plan?width:length*Math.abs(sy)*sp+width*Math.abs(cy)*sp+height*cp))*zoom;
 const targetY=focus?focus.y+focus.h/2:terrainMode?c.mountain*.25:floor+24,tx=focus?focus.x+focus.w/2:0,tz=focus?focus.z+focus.d/2:0;
 const proj=(x,y,z)=>{x-=tx;z-=tz;const a=plan?x:x*cy-z*sy,b=plan?z:x*sy+z*cy;return {x:w/2+a*scale,y:h/2+(b*(plan?1:sp)-(plan?0:y-targetY)*cp)*scale,depth:b*cp+(y-targetY)*sp};};
 const faces=[],polys=[],labels=[];
 const add=(v,fill,stroke,id=null,alpha=1)=>{const p=v.map(q=>proj(...q));faces.push({p,fill,stroke,id,alpha,depth:p.reduce((s,a)=>s+a.depth,0)/p.length});};
 const poly=(points,fill,stroke,alpha=1)=>{ctx.globalAlpha=alpha;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.8;ctx.stroke();}ctx.globalAlpha=1;};
 const prism=(polygon,y,height,fill,stroke,id=null,alpha=1)=>{for(let i=0;i<polygon.length;i++){const a=polygon[i],b=polygon[(i+1)%polygon.length];if(!plan)add([[...a.slice(0,1),y,a[1]],[b[0],y,b[1]],[b[0],y+height,b[1]],[a[0],y+height,a[1]]],fill,stroke,id,alpha*.45);}add(polygon.map(([x,z])=>[x,y+(plan?0:height),z]),fill,stroke,id,alpha);};
 if(terrainMode||surface){for(const v of terrainMesh(layout)){add(v,terrainColor(v),null,null,terrainMode?1:.15);const water=waterPolygon(v);if(water.length>2)add(water,'#498c9f',null,null,terrainMode?.84:.18);}}
 if(terrainMode)for(const r of layout.rooms.filter(r=>r.openToSky)){prism(r.polygon,r.y,r.h,'#e3b76b','#e3b76b',r.id,.2);add(r.polygon.map(([x,z])=>[x,r.y,z]),'#141724','#e3b76b',r.id,1);}
 if(!terrainMode){for(const r of layout.rooms.filter(r=>(!r.edgeSection||r.id===state.focusRoom)&&(onDeck(r,deck)||(stack&&!plan)))){const active=onDeck(r,deck),color=selected===r.id?'#ffe5a6':colors[r.type],alpha=active?(r.type==='transit'?.28:r.type==='station'||r.type==='rail'?.6:.5):.075;for(const v of roomVolumes(r))prism(v.polygon,v.y,v.h,color,active?color:color+'55',active?r.id:null,alpha);
 if(active&&['communal','activity'].includes(r.type)){const t=r.frameThickness;for(const [x,z] of [[r.x+r.w*.3,r.z+r.d*.3],[r.x+r.w*.7,r.z+r.d*.3],[r.x+r.w*.3,r.z+r.d*.7],[r.x+r.w*.7,r.z+r.d*.7]])prism([[x-t/2,z-t/2],[x+t/2,z-t/2],[x+t/2,z+t/2],[x-t/2,z+t/2]],r.y,roomHeightAt(r,x,z),'#d6cba8','#f2dfb0',null,.55);if(scale>.4)labels.push({text:r.type==='communal'?'Hall':r.name.split(' ')[0],p:proj(r.x+r.w/2,r.y+r.h,r.z+r.d/2),color});}}
 for(const rail of layout.rails.filter(r=>!r.edgeRoute&&(onDeck(r,deck)||(stack&&!plan)))){for(let k=1;k<rail.path.length;k++){const a=rail.path[k-1],b=rail.path[k],v=[[a[0],a[1],a[2]-2],[b[0],b[1],b[2]-2],[b[0],b[1],b[2]+2],[a[0],a[1],a[2]+2]];add(v,'#74b9ed','#89c7ff',null,rail.deck===deck?1:.18);}for(const id of [rail.a,rail.b]){const r=layout.rooms.find(r=>r.id===id);if(rail.deck===deck)labels.push({text:'[R]',p:proj(r.x+r.w/2,r.y+7,r.z+r.d/2),color:'#9ed8ff',dy:18});}}
 for(const l of layout.lifts.filter(l=>l.deck===deck)){const q=3;prism([[l.x-q,l.z-q],[l.x+q,l.z-q],[l.x+q,l.z+q],[l.x-q,l.z+q]],l.y,l.top-l.y,'#ead094','#f5e1a2',null,.35);labels.push({text:'[E]',p:proj(l.x,l.top,l.surfaceZ||l.z),color:'#ffe5a6',dy:-12});}
 for(const s of layout.skylights.filter(s=>deck===0||stack)){const a=s.width/2,b=s.depth/2;prism([[s.x-a,s.z-b],[s.x+a,s.z-b],[s.x+a,s.z+b],[s.x-a,s.z+b]],s.bottom,s.top-s.bottom,'#f8e9b0','#e7dba5',null,.13);}}
 if(!terrainMode)for(const well of layout.lightWells||[]){const galleries=well.galleries.filter(g=>g.deck===deck||(stack&&!plan));if(!galleries.length)continue;const a=well.width/2;prism([[well.x-a,well.z-a],[well.x+a,well.z-a],[well.x+a,well.z+a],[well.x-a,well.z+a]],Math.min(...galleries.map(g=>g.path[0][1])),well.top-Math.min(...galleries.map(g=>g.path[0][1])),'#ebdfb8','#efe2b0',null,.12);for(const g of galleries)for(let i=1;i<g.path.length;i++){const p=g.path[i-1],q=g.path[i],dx=q[0]-p[0],dz=q[2]-p[2],len=Math.hypot(dx,dz)||1,nx=-dz/len*g.width/2,nz=dx/len*g.width/2;add([[p[0]+nx,p[1],p[2]+nz],[q[0]+nx,q[1],q[2]+nz],[q[0]-nx,q[1],q[2]-nz],[p[0]-nx,p[1],p[2]-nz]],'#fff1ba','#dfd4a344',null,.12);}}
 // Small surface lanterns and elevator terminals, anchored to generated terrain.
 if(terrainMode||surface){for(const b of [...layout.terminals,...layout.skylights,...layout.lightWells]){const id=b.station||b.room||b.galleries?.[0]?.room;for(const f of structureFaces(b,layout.terrain))add(f.v,f.color,null,id,.98);labels.push({text:b.station?'[E] / [R]':b.galleries?'Light well':'Skylight',p:proj(b.x,b.top,b.z),color:'#eee1bc',dy:-12});}}
 if(terrainMode)for(const rail of layout.rails.filter(r=>r.waterCrossings.length)){for(let i=1;i<rail.path.length;i++){const a=rail.path[i-1],b=rail.path[i];add([[a[0],a[1],a[2]-3],[b[0],b[1],b[2]-3],[b[0],b[1],b[2]+3],[a[0],a[1],a[2]+3]],'#80b8ff','#c6e3ff');}const p=rail.path[1];labels.push({text:'[R] sealed lake crossing',p:proj(p[0],2,p[2]),color:'#b5dbff',dy:-12});}

 faces.sort((a,b)=>a.depth-b.depth);for(const f of faces){poly(f.p,f.fill,f.stroke,f.alpha);if(f.id)polys.push({id:f.id,points:f.p});}
 ctx.textAlign='center';ctx.font='12px sans-serif';for(const label of labels){ctx.fillStyle='#0a141cee';ctx.fillRect(label.p.x-ctx.measureText(label.text).width/2-3,label.p.y+(label.dy||0)-10,ctx.measureText(label.text).width+6,16);ctx.fillStyle=label.color;ctx.fillText(label.text,label.p.x,label.p.y+(label.dy||0)+2);}
 if(!terrainMode){if(path.length){ctx.setLineDash([6,4]);ctx.lineWidth=2;ctx.strokeStyle='#fff5c1';ctx.beginPath();let begun=false;for(const id of path){const r=layout.rooms.find(r=>r.id===id);if(!r||plan&&r.deck!==deck)continue;const p=proj(r.x+r.w/2,r.y+r.h+.8,r.z+r.d/2);if(begun)ctx.lineTo(p.x,p.y);else{ctx.moveTo(p.x,p.y);begun=true;}}ctx.stroke();ctx.setLineDash([]);}
 const r=layout.rooms.find(r=>r.id===(start||selected)&&onDeck(r,deck))||layout.rooms.find(r=>onDeck(r,deck)&&['communal','activity'].includes(r.type));if(r){drawAvatar(ctx,proj,r.x+r.w/2,r.y,r.z+r.d/2);const p=proj(r.x+r.w/2,r.y+1.95,r.z+r.d/2);ctx.fillStyle='#fff0c2';ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill();}}
 return {polys,scale};}
